'use client';

import React, { useEffect, useState } from 'react';
// import { Breadcrumbs } from '../../components/Breadcrumbs';
import styles from './FavoritesPage.module.scss';
import { Product } from '@/types/ProductType';
import { ProductCard } from '@/components/ProductCard';
import { ProductsList } from '@/components/ProductsList';
import { useRouter } from 'next/router';

const startForm = {
  category: '',
  itemId: '',
  price: '',
  image: '',
  name: '',
  screen: '',
  ram: '',
  camera: '',
  color: '',
  capacity: '',
  year: '',
  colorsAvailable: '',
  capacityAvailable: '',
  namespaceId: '',
};

export const Prisma = () => {
  const [mounted, setMounted] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [category, setCategory] = useState<'products' | 'phones' | 'tablets'>('products');
  const [selectedFile, setSelectedFile] = useState([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  // const router = useRouter();
  // const { category } = router.query;

  console.log(products);

  const [form, setForm] = useState({ ...startForm });

  useEffect(() => {
    setMounted(true);

    const fetchProducts = async () => {
      try {
        const res = await fetch(`/api/products?category=${category}`);
        const data = await res.json();

        if (!res.ok) {
          console.error('Server response:', data);
          throw new Error(`HTTP error! status: ${res.status}`);
        }

        setProducts(Array.isArray(data) ? data : []);
      } catch (err) {
        console.error('Fetch error:', err);
        setProducts([]);
      }
    };

    fetchProducts();
  }, [category]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);

    let imageUrls = [];

    // якщо створюємо новий продукт — фото обов'язкове
    if (!editingId && !selectedFile?.length) {
      return alert('Вибери файл');
    }

    // якщо файли вибрані — завантажуємо
    if (selectedFile?.length > 0) {
      imageUrls = await uploadImages(selectedFile);
    }

    const payload: any = {
      itemId: form.itemId,
      category: form.category,
      name: form.name,
      fullPrice: Number(form.price) || 0,
      price: Number(form.price) || 0,
      screen: form.screen || '',
      capacity: form.capacity || '',
      color: form.color || '',
      ram: form.ram || '',
      year: form.year || 2000,
      image: imageUrls[0] || form.image, // ← якщо не міняли, беремо старе
    };

    if (form.category) {
      payload.details = {
        name: form.name,
        screen: form.screen || 'unknown',
        ram: form.ram || 'unknown',
        camera: form.camera || 'unknown',
        resolution: 'unknown',
        processor: 'unknown',
        zoom: 'unknown',
        capacity: form.capacity || 'unknown',
        priceRegular: Number(form.price) || 0,
        priceDiscount: Number(form.price) || 0,
        color: form.color || '',
        images: imageUrls.length ? imageUrls : [], // ← залишаємо пусто, якщо не оновлювали
        cell: ['GPRS', 'EDGE'],
        capacityAvailable: form.capacityAvailable.split(',').map((s) => s.trim()) || [],
        colorsAvailable: form.colorsAvailable.split(',').map((s) => s.trim()) || [],
        description: [
          {
            title: 'Always-On Retina display',
            text: [
              'A transformative triple-camera system that adds tons of capability without complexity.An unprecedented leap in battery life.',
              'And a mind-blowing chip that doubles down on machine learning and pushes the boundaries of what a smartphone can do.',
            ],
          },
        ],
        namespaceId: form.namespaceId || '',
      };
    }

    try {
      const method = editingId ? 'PUT' : 'POST'; // <---- ГОЛОВНЕ
      const url = '/api/products';

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      const data = await res.json();

      if (!res.ok) {
        console.error('Server response:', data);
        throw new Error(`HTTP error! status: ${res.status}`);
      }

      if (editingId) {
        // update
        setProducts((prev) => prev.map((p) => (p.itemId === editingId ? { ...p, ...payload } : p)));

        setEditingId(null);
      } else {
        // create
        setProducts((prev) => [data.product, ...prev]);
      }

      setForm({ ...startForm });
      setSelectedFile([]);
    } catch (err) {
      console.error('Error creating product:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (product: Product) => {
    setEditingId(product.itemId); // позначаємо, що редагуємо
    setForm({
      category: product.category || '',
      itemId: product.itemId || '',
      price: product.price || '',
      image: product.image || '',
      name: product.name || '',
      screen: product.screen || '',
      ram: product.ram || '',
      camera: '',
      color: product.color || '',
      year: product.year?.toString() || '',
      capacity: product.capacity || '',
      capacityAvailable: '',
    });
  };

  const handleDelete = async (itemId: string) => {
    if (!confirm('Точно видалити цей товар?')) return;

    try {
      const res = await fetch(`/api/products?itemId=${itemId}`, {
        method: 'DELETE',
      });

      const data = await res.json();
      console.log('DELETE result:', data);

      if (!res.ok) {
        alert('Помилка: ' + data.error);
        return;
      }

      // Якщо все ок — онови список
      setProducts((prev) => prev.filter((p) => p.itemId !== itemId));

      alert('Товар успішно видалено');
    } catch (err: any) {
      console.error(err);
      alert('Сталася помилка при видаленні');
    }
  };

  async function uploadImages(files: File[]) {
    const urls: string[] = [];

    for (const file of files) {
      const reader = new FileReader();

      const url = await new Promise<string>((resolve, reject) => {
        reader.onloadend = async () => {
          const base64 = reader.result;

          try {
            const res = await fetch('/api/upload', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ file: base64 }),
            });

            if (!res.ok) {
              reject(`Upload failed for ${file.name}`);
              return;
            }

            const data = await res.json();
            resolve(data.url);
          } catch (err) {
            reject(err);
          }
        };

        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      urls.push(url);
    }

    return urls;
  }

  return (
    <div className='container'>
      {/* <Breadcrumbs /> */}
      <div className={styles.productsGrid}>
        {!loading && (
          <ProductsList products={products} onEdit={handleEdit} onDelete={handleDelete} />
        )}
      </div>

      <section className='section'>
        <form onSubmit={handleSubmit}>
          <input
            name='itemId'
            placeholder='Item ID'
            value={form.itemId}
            onChange={handleChange}
            required
          />
          <input
            name='namespaceId'
            placeholder='Namespace Id'
            value={form.namespaceId}
            onChange={handleChange}
            required
          />
          <input name='name' placeholder='Name' value={form.name} onChange={handleChange} />
          <input
            name='price'
            placeholder='Price'
            type='number'
            value={form.price}
            onChange={handleChange}
          />
          <input
            type='file'
            multiple
            accept='image/*'
            onChange={(e) => setSelectedFile(e.target.files)}
          />
          <input
            name='category'
            placeholder='Category'
            value={form.category}
            onChange={handleChange}
          />
          <textarea name='name' placeholder='name' value={form.name} onChange={handleChange} />

          <input name='screen' placeholder='Screen' value={form.screen} onChange={handleChange} />
          <input name='ram' placeholder='RAM' value={form.ram} onChange={handleChange} />
          <input name='camera' placeholder='Camera' value={form.camera} onChange={handleChange} />
          <input
            name='capacity'
            placeholder='Capacity'
            value={form.capacity}
            onChange={handleChange}
          />
          <input
            name='colorsAvailable'
            placeholder='Colors'
            value={form.colorsAvailable}
            onChange={handleChange}
          />
          <input name='color' placeholder='Color' value={form.color} onChange={handleChange} />

          <button type='submit'>Add Product</button>
        </form>
      </section>
    </div>
  );
};

export default Prisma;
